<?php
require_once 'config/database.php';require_once 'includes/functions.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){$pid=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);if($pid<1||$qty<1){flash('Select a product and enter a quantity greater than zero.','danger');header('Location: sales.php');exit;}try{$conn->begin_transaction();$st=$conn->prepare('SELECT id,name,selling_price,quantity FROM products WHERE id=? FOR UPDATE');$st->bind_param('i',$pid);$st->execute();$p=$st->get_result()->fetch_assoc();if(!$p)throw new Exception('Product not found.');if($p['quantity']<$qty)throw new Exception('Not enough stock available. Current stock: '.$p['quantity']);$price=(float)$p['selling_price'];$total=$price*$qty;$uid=(int)$_SESSION['user_id'];$st=$conn->prepare('INSERT INTO sales(user_id,total) VALUES(?,?)');$st->bind_param('id',$uid,$total);$st->execute();$saleId=$conn->insert_id;$sub=$total;$st=$conn->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,subtotal) VALUES(?,?,?,?,?,?)');$st->bind_param('iisidd',$saleId,$pid,$p['name'],$qty,$price,$sub);$st->execute();$st=$conn->prepare('UPDATE products SET quantity=quantity-? WHERE id=?');$st->bind_param('ii',$qty,$pid);$st->execute();$conn->commit();flash('Sale #'.$saleId.' recorded. Total: '.money($total));header('Location: sales_history.php');exit;}catch(Throwable $e){$conn->rollback();flash($e->getMessage(),'danger');header('Location: sales.php');exit;}}
$products=$conn->query('SELECT id,name,sku,selling_price,quantity FROM products WHERE quantity>0 ORDER BY name');$pageTitle='Record Sale';$active='sales';require 'includes/header.php';?><div class="row"><div class="col-md-8"><div class="card card-success"><div class="card-header"><h3 class="card-title">New Sale</h3></div><form method="post" id="saleForm"><div class="card-body"><div class="form-group"><label>Product *</label><select name="product_id" id="product" class="form-control" required><option value="">Choose product</option><?php while($p=$products->fetch_assoc()):?><option value="<?=$p['id']?>" data-price="<?=$p['selling_price']?>" data-stock="<?=$p['quantity']?>"><?=e($p['name'])?> (<?=e($p['sku'])?>) — stock <?=$p['quantity']?> — <?=money($p['selling_price'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Quantity *</label><input type="number" min="1" name="quantity" id="quantity" class="form-control" required value="1"></div><div class="alert alert-info">Available stock: <strong id="stock">-</strong><br>Estimated total: <strong id="total">TZS 0.00</strong></div><button class="btn btn-success" type="submit"><i class="fas fa-check mr-1"></i>Complete Sale</button></div></form></div></div><div class="col-md-4"><div class="callout callout-info"><h5>Sales process</h5><p>Select a product and quantity. The system checks stock, records the sale, calculates the total, and reduces stock automatically in one database transaction.</p></div></div></div><script>const product=document.getElementById('product'),quantity=document.getElementById('quantity');function calc(){const o=product.options[product.selectedIndex],price=Number(o.dataset.price||0),stock=Number(o.dataset.stock||0),q=Number(quantity.value||0);document.getElementById('stock').textContent=product.value?stock:'-';document.getElementById('total').textContent='TZS '+(price*q).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});quantity.max=stock;}product.addEventListener('change',calc);quantity.addEventListener('input',calc);document.getElementById('saleForm').addEventListener('submit',e=>{if(Number(quantity.value)>Number(product.options[product.selectedIndex].dataset.stock||0)){e.preventDefault();alert('Quantity exceeds available stock.')}});calc();</script><?php require 'includes/footer.php';?>
